  const run = (args) => spawnSync(process.env.TERRAFORM_BINARY || "terraform", args, {
    cwd: join(dir, "terraform/modules/ecs-runtime"), env, encoding: "utf8", timeout: 800_000, maxBuffer: 16 * 1024 * 1024
