data "aws_iam_principal_policy_simulation" "pre_arm" {
  for_each = { for pair in setproduct(keys(local.role_specs), local.documents) : "${pair[0]}/${pair[1]}" => pair if var.simulation_enabled && local.live[pair[0]].exists }
  policy_source_arn = "arn:aws:iam::${var.aws_account_id}:role/${local.role_specs[each.value[0]].role_name}"
