  for_each           = local.role_specs
  name               = each.value.role_name
  description        = try(each.value.description, null)
  assume_role_policy = jsonencode(local.armed[each.key] ? each.value.assume_role_policy : local.inert_trust)
  tags               = merge(var.tags, try(each.value.extra_tags, {}), { RoleCategory = each.value.category })
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = !var.simulation_enabled || var.inventory_required
