    }
    precondition {
      condition = try(length(each.value.assume_role_policy.Statement) == 1 &&
        each.value.assume_role_policy.Statement[0].Effect == "Allow" &&
        each.value.assume_role_policy.Statement[0].Action == "sts:AssumeRoleWithWebIdentity" &&
        each.value.assume_role_policy.Statement[0].Principal.Federated == "arn:aws:iam::${var.aws_account_id}:oidc-provider/token.actions.githubusercontent.com" &&
